+    private function is_transient_provider_error( string $error_message ): bool {
+        $transient_patterns = [
+            '/HTTP 502/i',
+            '/HTTP 503/i',
+            '/cURL error 28/i',
+            '/cURL error 52/i',
+            '/Operation timed out/i',
+            '/Empty reply from server/i',
+        ];
+
+        foreach ( $transient_patterns as $pattern ) {
+            if ( preg_match( $pattern, $error_message ) ) {
+                return true;
+            }
+        }
+
+        return false;
+    }
